Output385Avoiding the overflow: In the above method, sometimes due to large value of n, the value of (n * (n + 1) * (2 * n + 1)) would overflow. We can avoid this overflow up to some extent using the fact that n*(n+1) must be divisible by 2 and restructuring the formula as (n * (n + 1) / 2) * (2 * n + 1) / 3;
            C++

    #include <iostream>
using namespace std;


int summation(int n)
{
//to avoid overflow 
//n*(n + 1)*(2 * n + 1) / 6 = (n * (n + 1) / 2) * (2 * n + 1) / 3;
    return (n * (n + 1) / 2) * (2 * n + 1) / 3;
}


int main()
{
    int n = 10;
    cout << summation(n) << endl;
    return 0;
}


